export const POINTER = /^[A-Z][^:]{0,40}: see (.+)\.$/;

// The front states the card's own buying ladder; a family card's front may name the owned
// standard (e.g. "100% grass-fed and grass-finished."), the depth may not.
export const REPEATED_CLAIM_FIELDS = [
  'why', 'short_answer', 'detail', 'science', 'kristy_take', 'tier_note',
  'pick_steps', 'buying_tips', 'look_for', 'watch_out', 'labels_decoded',
];

// Every string under a value, in order: prose fields hold strings, arrays and objects.
export function stringsIn(v, out = []) {
  if (typeof v === 'string') out.push(v);
  else if (Array.isArray(v)) v.forEach((x) => stringsIn(x, out));
  else if (v && typeof v === 'object') Object.values(v).forEach((x) => stringsIn(x, out));
  return out;
}

export function lintRepeatedClaim(entry) {
  const out = [];
  for (const row of OWNED_FACTS) {
    if (!row.family.includes(entry?.id)) continue;
    for (const field of REPEATED_CLAIM_FIELDS) {
      if (entry[field] == null) continue;
      // A labels_decoded `term` is the label's own printed word (like an alias); its meaning is still scanned.
      const value = field === 'labels_decoded' && Array.isArray(entry[field])
        ? entry[field].map((i) => (i && typeof i === 'object' ? { ...i, term: undefined } : i))
        : entry[field];
      for (const text of stringsIn(value)) {
        // L4 requires the section's canonical gloss on a family card, so the gloss itself is not a repeat.
        const unglossed = CANONICAL_GLOSSES.reduce((t, g) => t.split(g.gloss).join(''), text);
        if (!POINTER.test(text) && row.pattern.test(unglossed)) out.push({ code: 'REPEATED_CLAIM', fact: row.fact, field, text });
      }
    }
  }
  const titles = new Set(OWNED_FACTS.map((r) => r.ownerTitle));
  for (const text of stringsIn(entry?.pick_steps)) {
    const m = text.match(POINTER);
    if (m && !titles.has(m[1])) out.push({ code: 'POINTER_UNKNOWN_OWNER', field: 'pick_steps', text });
  }
  return out;
}

